const setText=(node,value)=>{if(node&&node.textContent!==value)node.textContent=value;};
export class TrainBoarding200{
 constructor(player,doc){this.player=player;this.view=player.view;this.doc=doc;this.portals=new WeakMap();const stage=player.canvas.parentElement;if(stage&&doc.createElement){this.button=doc.createElement('button');this.button.type='button';this.button.className='ride200-action';this.button.hidden=true;this.button.setAttribute('aria-label','Subir o bajar del tren');this.button.onclick=()=>this.interact();stage.append(this.button);}}
 get trainId(){return this.aboard?.trainId||this.transition?.trainId;}
 reset(){this.aboard=null;this.transition=null;if(this.button)this.button.hidden=true;}
 train(){return this.view.getState()?.engine?.trains.find(t=>t.id===this.trainId);}
 localPortals(model,train){if(!model?.detailed||!model.group||!this.view.doorPortals)return[];let list=this.portals.get(model.group);if(!list){model.group.updateWorldMatrix(true,true);list=this.view.doorPortals(model,train).map(p=>model.group.worldToLocal(new T.Vector3(p.x,2.83,p.z)));this.portals.set(model.group,list);}return list;}
 canCross(train,entering=true){const e=this.view.getState().engine,line=e.lines?.[train.line],center=line?.distances?.[train.target],phase=e.operator?.trainId===train.id?e.operator.phase:null;return Math.abs(train.speed||0)<.01&&train.wait>(entering?4:1.5)&&(!Number.isFinite(center)||Math.abs(train.position-center)<1.5)&&(!entering||phase!=='warning')&&doorOpenness(e,train)>=.95;}
 nearby(){const v=this.view,state=v.getState();let best=null;for(const t of state.engine.trains){if(t.line!==state.currentLine)continue;const model=v.trainMeshes?.get(t.id);if(!model?.group.visible||!model.detailed)continue;model.group.updateWorldMatrix(true,true);for(const local of this.localPortals(model,t)){const point=model.group.localToWorld(local.clone()),d=Math.hypot(point.x-v.camera.position.x,point.z-v.camera.position.z);if(!best||d<best.distance)best={train:t,model,point,local,distance:d};}}return best;}
 insideDoor(){const t=this.train(),model=this.view.trainMeshes?.get(t?.id);if(!this.aboard||!t||!model)return null;let best=null;for(const local of this.localPortals(model,t)){const distance=Math.hypot(local.x-this.aboard.local.x,local.z-this.aboard.local.z);if(!best||distance<best.distance)best={train:t,model,local,point:model.group.localToWorld(local.clone()),distance};}return best;}
 hint(){if(this.button)this.button.hidden=!this.player.active();if(!this.player.active())return;let label;if(this.transition)label=this.transition.kind==='enter'?'Entrando al vagón…':'Bajando al andén…';else if(this.aboard){const door=this.insideDoor();label=door&&door.distance<1.65&&this.canCross(door.train,false)?'E · Bajar al andén':'A bordo · WASD: recorrer el vagón · E: bajar al detenerse';}else{const door=this.nearby();label=door&&door.distance<1.75?(this.canCross(door.train)?'E · Subir al tren':'Espera al tren detenido y con puertas abiertas'):'Acércate a una puerta · E para subir';}setText(this.button,label);}
 interact(){if(this.transition)return false;if(this.aboard){const door=this.insideDoor();if(door&&door.distance<1.65&&this.canCross(door.train,false))return this.start(door,'exit');this.hint();return false;}const door=this.nearby();if(door&&door.distance<1.75&&this.canCross(door.train))return this.start(door,'enter');this.hint();return false;}
 start(door,kind){const v=this.view,line=v.getState().engine.lines[door.train.line],center=line.distances[door.train.target],station=v.stationCache?.get(door.train.target),side=door.point.z<0?-1:1;if(Math.abs(door.point.x-center)>68.5)return false;let target;
  if(kind==='enter'){target=door.local.clone();target.z=Math.sign(target.z)*.58;}else{const p=safePlatformPoint169({x:door.point.x-center,z:side*4.3},side,station?.userData.solids169||[],.3);target=door.model.group.worldToLocal(new T.Vector3(center+p.x,v.camera.position.y,p.z));}
  this.transition={kind,trainId:door.train.id,from:door.model.group.worldToLocal(v.camera.position.clone()),target,elapsed:0,center,station:door.train.target,line:door.train.line};this.player.keys.clear();this.hint();return true;
 }
 walk(delta,dt,eye){const v=this.view;
  if(this.trainId){const t=this.train(),model=v.trainMeshes?.get(t?.id);if(!t||!model?.detailed||t.line!==v.getState().currentLine){this.reset();return false;}model.group.updateWorldMatrix(true,true);
   if(this.transition){const p=this.transition;p.elapsed+=dt;const u=T.MathUtils.clamp(p.elapsed/.75,0,1),k=u*u*(3-2*u),local=p.from.clone().lerp(p.target,k);local.y=T.MathUtils.lerp(local.y,eye,k);if(!this.canCross(t,p.kind==='enter')){if(p.kind==='enter'){v.camera.position.copy(model.group.localToWorld(p.from.clone()));this.transition=null;this.hint();return false;}this.transition=null;}else{v.camera.position.copy(model.group.localToWorld(local));if(u===1){this.transition=null;if(p.kind==='enter')this.aboard={trainId:t.id,local:p.target.clone(),direction:t.direction};else{this.aboard=null;v.platformStation=p.station;v.cameraStation=p.station;v.platformSide169=v.camera.position.z<0?-1:1;v.fixedAnchor=p.center;v.previousPlatform169=null;globalThis.window?.pinSceneStation?.(v.getState().engine.lines[p.line].stations[p.station].id);}}this.hint();return true;}}
   if(this.aboard){const a=this.aboard;if(a.direction!==t.direction){a.local.x=-a.local.x;a.local.z=-a.local.z;a.direction=t.direction;}const movement=delta.clone().applyQuaternion(model.group.getWorldQuaternion(new T.Quaternion()).invert()),to=a.local.clone().add(movement),car=Math.max(-4,Math.min(4,Math.round(a.local.x/16.7))),center=car*16.7,doors=this.localPortals(model,t),vestibule=doors.some(p=>Math.abs(p.x-to.x)<.65);to.x=T.MathUtils.clamp(to.x,center-6.5,center+6.5);const aisle=t.line===1?.55:.34;if(!vestibule&&Math.abs(a.local.z)>aisle&&Math.abs(to.z)>aisle){to.x=a.local.x;to.z=T.MathUtils.clamp(to.z,-Math.abs(a.local.z),Math.abs(a.local.z));}else to.z=T.MathUtils.clamp(to.z,vestibule?-1.08:-aisle,vestibule?1.08:aisle);
    const door=this.insideDoor();if(door&&vestibule&&Math.abs(to.z)>1.02&&to.z*door.local.z>0&&Math.abs(door.local.x-to.x)<.65&&this.canCross(t,false)){this.start(door,'exit');return true;}
    // Keep the student outside standing passengers without snapping through them.
    const actors=(v.actors180||[]).filter(p=>p.location==='cabin'&&p.pose!=='seated').map(p=>model.group.worldToLocal(new T.Vector3(p.x,eye,p.z))).filter(p=>Math.abs(p.x-to.x)<1&&Math.abs(p.z-to.z)<1);let p=a.local.clone();const steps=Math.max(1,Math.ceil(p.distanceTo(to)/.06)),d=to.clone().sub(p).multiplyScalar(1/steps);for(let i=0;i<steps;i++){const q=p.clone().add(d);if(!actors.some(b=>Math.hypot(q.x-b.x,q.z-b.z)<.39&&q.distanceTo(b)<p.distanceTo(b)))p.copy(q);}p.y=T.MathUtils.lerp(p.y,eye,1-Math.exp(-12*dt));a.local.copy(p);v.camera.position.copy(model.group.localToWorld(a.local.clone()));this.hint();return true;}
  }
  const near=this.nearby();if(near&&this.canCross(near.train)&&near.distance<1.4&&Math.abs(near.point.x-v.camera.position.x)<.48&&delta.z*(near.point.z-v.camera.position.z)>0&&Math.abs(v.camera.position.z)<4.22){this.start(near,'enter');return true;}this.hint();return false;
 }
}
